import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"Making CephFS (Much More) Great! - Patrick Donnelly & Greg Farnum, IBM","description":"","frontmatter":{"title":"Making CephFS (Much More) Great! - Patrick Donnelly & Greg Farnum, IBM","date":"2023-05-09T00:00:00.000Z","updated":"2023-05-09T00:00:00.000Z","tags":["CephFS","分布式存储","Ceph","高可用性","可扩展性","故障恢复"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Making_CephFS_Much_More_Great_-_Patrick_Donnelly_Greg_Farnum_IBM.md","filePath":"posts/2023/Making_CephFS_Much_More_Great_-_Patrick_Donnelly_Greg_Farnum_IBM.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Making_CephFS_Much_More_Great_-_Patrick_Donnelly_Greg_Farnum_IBM.md"};function o(n,l,_,h,p,u){return a(),i("div",null,[...l[0]||(l[0]=[t('<p>会议纪要</p><h3 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h3><ul><li>主持人：Patrick（前CFS团队负责人，现参与Sepafest项目）</li><li>参与者：Greg（SEF Fest团队经理，前STL长期贡献者）及其他与会者</li></ul><h3 id="会议议题" tabindex="-1">会议议题 <a class="header-anchor" href="#会议议题" aria-label="Permalink to &quot;会议议题&quot;">​</a></h3><ol><li><p><strong>CFS多集群恢复能力</strong></p><ul><li>讨论了多集群故障恢复的难度和当前的不完善状态。</li><li>提出了改进建议，包括查看相关故障报告、社区讨论以及配置或升级解决方案。</li></ul></li><li><p><strong>MDS故障恢复</strong></p><ul><li>讨论了MDS在某些情况下会放弃的问题，通常在故障转移情况下可以恢复。</li><li>强调了Red Hat Ceph团队现在有更多客户，这些问题的出现频率增加，成为业务优先事项。</li></ul></li><li><p><strong>SMB与CephFS的集成</strong></p><ul><li>讨论了使用Samba VFS与CephFS集成的问题，包括Samba的工作方式和潜在的问题。</li><li>提出了改进建议，但目前没有具体的开发重点。</li></ul></li><li><p><strong>升级问题</strong></p><ul><li>讨论了从Nautilus升级到Quincy时的多活动MDS问题，特别是升级过程中的挑战。</li><li>提出了新的升级选项，如关闭整个CephFS文件系统进行升级，以避免不同版本的MDS相互通信的问题。</li></ul></li><li><p><strong>性能和稳定性改进</strong></p><ul><li>讨论了MDS缓存大小、客户端性能问题以及如何通过配置调整来改善。</li><li>提出了关于CephFS top工具的改进，以及如何更好地监控和收集客户端性能数据。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>需要进一步研究和改进CephFS的多集群恢复能力和MDS故障恢复机制。</li><li>需要关注和解决SMB与CephFS集成中的问题。</li><li>需要改进升级过程，特别是多活动MDS的升级策略。</li><li>需要增强CephFS的监控和性能数据收集能力。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>继续研究和开发多集群恢复和MDS故障恢复的解决方案。</li><li>关注和解决SMB与CephFS集成中的具体问题。</li><li>改进和优化CephFS的升级流程。</li><li>增强CephFS的监控和性能数据收集功能，特别是在客户端性能方面。</li></ul><h3 id="其他讨论点" tabindex="-1">其他讨论点 <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点&quot;">​</a></h3><ul><li>讨论了CephFS的快照和克隆功能的限制和改进建议。</li><li>讨论了CephFS的扩展属性和统计功能的实际应用和潜在改进。</li></ul><p>会议主要围绕CephFS的多个关键问题进行了深入讨论，包括故障恢复、集成问题、升级挑战和性能监控。会议强调了持续改进和用户反馈的重要性，并提出了具体的改进方向和行动计划。</p>',12)])])}const c=e(r,[["render",o]]);export{S as __pageData,c as default};
